public class CountA {
  public static void main(String[] args) {
    String s = "Java Programming Language";
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c == 'a' || c == 'A')
        count++;
    }
    System.out.println("a 出现的次数：" + count);
  }
}
